var solveNQueens = function(n) {
    const columns = new Set();
    const diagDown = new Set();
    const diagUp = new Set();
    const placement = new Array(n).fill(-1);
    const answers = [];

    const search = (row) => {
        if (row === n) {
            const board = [];
            for (const col of placement) {
                board.push('.'.repeat(col) + 'Q' + '.'.repeat(n - col - 1));
            }
            answers.push(board);
            return;
        }
        for (let col = 0; col < n; col++) {
            const down = row - col;
            const up = row + col;
            if (columns.has(col) || diagDown.has(down) || diagUp.has(up)) continue;
            columns.add(col);
            diagDown.add(down);
            diagUp.add(up);
            placement[row] = col;
            search(row + 1);
            columns.delete(col);
            diagDown.delete(down);
            diagUp.delete(up);
        }
    };

    search(0);
    return answers;
};
